# tw2de_nx (2026-11-02): the pack instructions with the destination also a source. The SDK wrote vD lane by lane,
# so with vD == vA (or vB) the halfwords / bytes written first overwrote source words not read yet: the game's
# vpkuwus128 v63,v63,v62 (sub_828B31B0, the physics' quantized ray box) made the z008 boat's floor ray miss.
# Expectations: the PowerPC definition (vD = saturated vA elements, then saturated vB elements), as the distinct-register
# cases give. Generated by hand from that definition; the first case of each instruction has no aliasing.

test_vpkuwus_alias_0:
  #_ REGISTER_IN v4 [0000000A, 000001F4, 000002BC, 00000000]
  #_ REGISTER_IN v5 [00000000, 000001E0, 0000028A, 00000000]
  vpkuwus v3, v4, v5
  blr
  #_ REGISTER_OUT v3 [000A01F4, 02BC0000, 000001E0, 028A0000]

test_vpkuwus_alias_1:
  #_ REGISTER_IN v3 [0000000A, 000001F4, 000002BC, 00000000]
  #_ REGISTER_IN v5 [00000000, 000001E0, 0000028A, 00000000]
  vpkuwus v3, v3, v5
  blr
  #_ REGISTER_OUT v3 [000A01F4, 02BC0000, 000001E0, 028A0000]

test_vpkuwus_alias_2:
  #_ REGISTER_IN v4 [0000000A, 000001F4, 000002BC, 00000000]
  #_ REGISTER_IN v3 [00000000, 000001E0, 0000028A, 00000000]
  vpkuwus v3, v4, v3
  blr
  #_ REGISTER_OUT v3 [000A01F4, 02BC0000, 000001E0, 028A0000]

test_vpkuwus_alias_3:
  #_ REGISTER_IN v3 [00010000, 00000005, FFFFFFFF, 00000007]
  vpkuwus v3, v3, v3
  blr
  #_ REGISTER_OUT v3 [FFFF0005, FFFF0007, FFFF0005, FFFF0007]

test_vpkuwus_alias_4:
  #_ REGISTER_IN v3 [00010000, 00000005, FFFFFFFF, 00000007]
  #_ REGISTER_IN v5 [0000000A, 000001F4, 000002BC, 00000000]
  vpkuwus v3, v3, v5
  blr
  #_ REGISTER_OUT v3 [FFFF0005, FFFF0007, 000A01F4, 02BC0000]

test_vpkuwus128_alias_5:
  #_ REGISTER_IN v63 [0000000A, 000001F4, 000002BC, 00000000]
  #_ REGISTER_IN v62 [00000000, 000001E0, 0000028A, 00000000]
  vpkuwus128 v63, v63, v62
  blr
  #_ REGISTER_OUT v63 [000A01F4, 02BC0000, 000001E0, 028A0000]

test_vpkuhus_alias_0:
  #_ REGISTER_IN v4 [000100FF, 0100FFFF, 00100020, 7FFF8000]
  #_ REGISTER_IN v5 [00020003, 000000FE, 01010004, 00050006]
  vpkuhus v3, v4, v5
  blr
  #_ REGISTER_OUT v3 [01FFFFFF, 1020FFFF, 020300FE, FF040506]

test_vpkuhus_alias_1:
  #_ REGISTER_IN v3 [000100FF, 0100FFFF, 00100020, 7FFF8000]
  #_ REGISTER_IN v5 [00020003, 000000FE, 01010004, 00050006]
  vpkuhus v3, v3, v5
  blr
  #_ REGISTER_OUT v3 [01FFFFFF, 1020FFFF, 020300FE, FF040506]

test_vpkuhus_alias_2:
  #_ REGISTER_IN v4 [000100FF, 0100FFFF, 00100020, 7FFF8000]
  #_ REGISTER_IN v3 [00020003, 000000FE, 01010004, 00050006]
  vpkuhus v3, v4, v3
  blr
  #_ REGISTER_OUT v3 [01FFFFFF, 1020FFFF, 020300FE, FF040506]

test_vpkuhus_alias_3:
  #_ REGISTER_IN v3 [000100FF, 0100FFFF, 00100020, 7FFF8000]
  vpkuhus v3, v3, v3
  blr
  #_ REGISTER_OUT v3 [01FFFFFF, 1020FFFF, 01FFFFFF, 1020FFFF]
